function onSave()
    savedData.firstPlayerVersion = firstPlayerVersion
    savedData.autoTurn = autoTurn
    savedData.autoGame = autoGame
    savedData.speedIndex = speedIndex
    savedData.sizeIndex = sizeIndex
    savedData.setTurns = setTurns
    savedData.showSettings = showSettings
    savedData.setTurnOnWin = setTurnOnWin
    savedData.broadcastTurns = broadcastTurns
    savedData.broadcastWins = broadcastWins
    savedData.destroyOnWin = destroyOnWin
    self.script_state = JSON.encode(savedData)
end

function loadSavedValues()
    firstPlayerVersion = savedData.firstPlayerVersion
    autoTurn = savedData.autoTurn
    autoGame = savedData.autoGame
    speedIndex = savedData.speedIndex
    sizeIndex = savedData.sizeIndex
    setTurns = savedData.setTurns
    showSettings = savedData.showSettings
    setTurnOnWin = savedData.setTurnOnWin
    broadcastTurns = savedData.broadcastTurns
    broadcastWins = savedData.broadcastWins
    destroyOnWin = savedData.destroyOnWin
end

function leftClick(player, mouse, id)
    if mouse ~= '-1' and mouse ~= '0' then
        return
    end
    local run = self.UI.getAttribute(id,"func")
    if run ~= "" and run ~= nil then
        _G[run]()
    end
end

function toggleSettings()
    if showSettings then
        showSettings = false
        self.UI.hide("pnlSettings")
        self.UI.setAttribute("btnToggleSettings", "text", toggleText(showSettings))
    else
        showSettings = true
        self.UI.show("pnlSettings")
        self.UI.setAttribute("btnToggleSettings", "text", toggleText(showSettings))
    end
    onSave()
end

function toggleColor(on)
    if on then
        return "Green|Green"
    else
        return "Red|Red"
    end
end

function toggleText(on)
    if on then
        return "<"
    else
        return ">"
    end
end

function firstButtonColorShow(color)
    local colorTable  = {
        {"Red","White"},
        {"Purple", "White"},
        {"Yellow", "Black"},
        {"Blue", "Black"},
        {"Orange", "Black"},
        {"Green", "White"}
    }
    self.UI.setAttribute("btnFirstStartGame", "color", colorTable[color][1])
    self.UI.setAttribute("btnFirstStartGame", "textColor", colorTable[color][2])
    if color == tablelength(colorTable) then
        color = 1
    else
        color = color + 1
    end
    if not currentTurn and firstPlayerVersion then
        Wait.frames(function() firstButtonColorShow(color) end, 45)
    end
end

function toggleValue(player, mouse, id)
    if mouse ~= '-1' and mouse ~= '0' then
        return
    end
    local toggle = self.UI.getAttribute(id,"tgl")
    if _G[toggle] then
        _G[toggle] = false
        self.UI.setAttribute(id, "colors", toggleColor(false))
        self.UI.setAttribute(id, "isOn", "false")
        broadcastToAll(self.UI.getAttribute(id .. "Txt","text") .. " Disabled")
    else
        _G[toggle] = true
        self.UI.setAttribute(id, "colors", toggleColor(true))
        self.UI.setAttribute(id, "isOn", "true")
        broadcastToAll(self.UI.getAttribute(id .. "Txt","text") .. " Enabled")
        if toggle == "autoTurn" and currentTurn then
            nextTurn()
        elseif toggle == "autoGame" and gameEnd then
            playAgain()
        end
        
        if toggle == "autoTurn" and setTurns then
            toggleValue(nil, '-1', "tglSetTurns")
        end
    end
    onSave()
end

function incrementValue(player, mouse, id)
    if mouse ~= '-1' and mouse ~= '0' then
        return
    end
    local variable = self.UI.getAttribute(id,"var")
    local increment = self.UI.getAttribute(id,"inc")
    _G[variable .. "Index"] = _G[variable.. "Index"] + increment
    self.UI.setAttribute(variable .. "Display", "text", _G[variable .. "Table"][_G[variable .. "Index"]][1])
    if _G[variable .. "Index"] == tablelength(_G[variable .. "Table"]) then
        self.UI.hide(variable .. "IncUp")
    elseif _G[variable .. "Index"] == 1 then
        self.UI.hide(variable .. "IncDown")
    else
        self.UI.show(variable .. "IncUp")
        self.UI.show(variable .. "IncDown")
    end
    if variable == "size" then
        scaleAll()
    end
    broadcastToAll(self.UI.getAttribute(variable .. "Txt","text") .. " changed to " .. _G[variable .. "Table"][_G[variable .. "Index"]][1])
    onSave()
end

function scaleAll()
    resetPositions(true, true)
    self.setScale({sizeTable[sizeIndex][2],1,sizeTable[sizeIndex][2]})
    if playerList ~= nil then
        local snappoints = self.getSnapPoints()
        for i, player in ipairs(playerList) do
            player.pawn.setScale(self.getScale()*0.022)
            player.pawn.setCustomObject({thickness = self.getScale().x*0.022})
            player.pawn = player.pawn.reload()
        end
    end
    if deck ~= nil then
        deck.setScale(self.getScale()*0.13)
    end
    if discard ~= nil then
        discard.setScale(self.getScale()*0.13)
    end
end

function resetPositions(decks, pawns)
    local p = self.getPosition()
    local s = self.getScale()
    if pawns then
        if playerList ~= nil then
            local snappoints = self.getSnapPoints()
            for i, player in ipairs(playerList) do
                if player.space > 0 then
                    player.pawn.setPosition(self.positionToWorld(snappoints[player.space].position))
                    player.pawn.setRotation(snappoints[player.space].rotation)
                else
                    player.pawn.setPosition({(s.x*(-0.97-(0.04*(i-1))))+p.x, 2+(0.17*s.x)+p.y, (s.z*-0.92)+p.z})
                    player.pawn.setRotation({90,270,0})
                end
            end
        end
    end
    if decks then
        if deck ~= nil then
            deckPos = {(s.x*-1.2)+p.x,p.y,(s.z*1.22)+p.z}
            deck.setPosition(deckPos)
            deck.setRotation({180,180,0})
        end
        if discard ~= nil then
            discardPos = {(s.x*-0.85)+p.x,p.y,(s.z*1.22)+p.z}
            discard.setPosition(discardPos)
            discard.setRotation({0,180,0})
        end
    end
end

function onObjectDrop(colorName, obj)
    if obj == self  then
        resetPositions(true, false)
    end 
end

function manualMode()
    manual = true
    self.UI.hide("pnlSettings")
    self.UI.hide("btnToggleSettings")
    spawnPieces()
end

function startGame()
    gameEnd = false
    totalTurns = 0
    currentTurn = math.random(1, tablelength(playerList))
    Wait.frames(function() createNextTurnButton() end, 60)
end

function spawnPieces()
    menuCleanup()
    cleanUp()
    spawnDeck(deckFace, deckBack)
    piecesLoading = 0
    createPlayerList()
    if manual == false then
        Wait.frames(function() waitForLoading() end, 60)
    end
end

function waitForLoading()
    if piecesLoading == 0 then
        scaleAll()
        Wait.frames(function() startGame() end, 60)
    else
        Wait.frames(function() waitForLoading() end, 60)
    end
end

