    }
    playerList = {}
	for i, color in ipairs(playerColors) do
		if isComputerEnabled(color[1]) then
			piecesLoading = piecesLoading + 1
			createPlayer(color[1], color[2], color[1] .. " Computer")
		elseif isPlayerSeated(color[1]) then
			piecesLoading = piecesLoading + 1
			createPlayer(color[1], color[2], isPlayerSeated(color[1], true).steam_name)
		end
	end
end

function isPlayerSeated(color, info)
    local playerList = Player.getPlayers()
    for _, player in ipairs(playerList) do
        if (color ~= nil and color == player.color) 
            or (color == nil) then
            if info == nil then
                return true
            else
                return player
            end
        end
    end
    return false
end

function isComputerEnabled(color)
	for i, obj in ipairs(getAllObjects()) do
		if obj.getName() == color .. " Hand" then
			if obj.getPosition().y == 1 then
				return obj
			else
				return false
			end
		end
	end
	return false
end

function createPlayer(col, img, n)
    local p = self.getPosition()
    local s = self.getScale()
    local player = {
        name = n,
        color = col, 
        space = 0,
        turns = 0,
        loseTurn = false
    }
    local pos = {(s.x*(-0.97-(0.04*tablelength(playerList))))+p.x, (s.x*0.17)+p.y, (s.z*-0.92)+p.z}
    local var = spawnObject({ 
        type                = "Custom_Token",
        position            = pos, 
        scale               = self.getScale()*0.022,
        rotation            = {90,270,0}, 
        callback_function   = function(obj, player) obj.setName(n) piecesLoading = piecesLoading - 1 end
    })
            var.setCustomObject({image = img, thickness = self.getScale().x*0.022})
            player.pawn = var
    table.insert(playerList, player)
end

function tablelength(t)
    local count = 0
    for _ in pairs(t) do count = count + 1 end
    return count
end

function createNextTurnButton()
    if setTurns then
        setTurn(playerList[currentTurn].color)
    end
    if autoTurn then
        nextTurn()
    else
        local playerColor = playerList[currentTurn].color
        local fontColor = "White"
        if playerColor == "White" or playerColor == "Yellow" or playerColor == "Teal" then
            fontColor = "Black"
        end
        self.UI.show("btnTakeTurn")
        self.UI.setAttribute("btnTakeTurn", "color", playerColor)
        self.UI.setAttribute("btnTakeTurn", "text", "Take " .. playerList[currentTurn].name .. "'s Turn")
        self.UI.setAttribute("btnTakeTurn", "textColor", fontColor)
		local comp = isComputerEnabled(playerColor)
		if comp then
			local pos = comp.getPosition()
			local tPos = getTransformPosition(self, {x = 0, y = 0, z = 1.25*self.getScale().x})
			comp.setPositionSmooth(tPos, false, true)
			Wait.time(function()
				local rot = comp.getRotation()
				rot.z = 180
				comp.setRotation(rot)
				Wait.time(function()
					nextTurn()
					rot.z = 0
					comp.setRotation(rot)	
					Wait.time(function()
						comp.setPositionSmooth(pos, false, true)
					end, 0.5)
				end, 0.25)
			end, 0.5)
		end
	end
end

function getTransformPosition(object, pos)
    local cPos = object.getPosition()
    local fVal = object.getTransformForward()
    local rVal = object.getTransformRight()
    local uVal = object.getTransformUp()
    return {
        x = cPos.x + fVal.x*pos.z + rVal.x*pos.x + uVal.x*pos.y,
        y = cPos.y + fVal.y*pos.z + rVal.y*pos.x + uVal.y*pos.y,
        z = cPos.z + fVal.z*pos.z + rVal.z*pos.x + uVal.z*pos.y
    }
end

function createBoard()
    local colorTable  = {"Green","Red","Purple","Yellow","Blue","Orange"}
    local board = {}
    local value = 0
    local offset = 0
    for i = 1, 134, 1 do 
        item = addItem(i)
        if item then
            board[i] = item
            offset = offset + 1
        else
            value = (i-offset)%6 + 1
            board[i] = colorTable[value]
        end
    end
    return board
end

function addItem(index)
    for i, item in ipairs(itemTable) do
        if index == item[2] then
            return item[1]
        end
    end
end

function spawnDeck()
    local faceImg = "http://i.imgur.com/IGvZhkq.png"
    local backImg = "http://i.imgur.com/aaSng6y.png"
    local p = self.getPosition()
    local s = self.getScale()
    deck = spawnObject({ 
        type                = "DeckCustom",
        position            = {(s.x*-1.2)+p.x,1.3+p.y,(s.z*1.22)+p.z}, 
        scale               = self.getScale()*0.13,
        rotation            = {0,180,180}, 
        callback_function   = function(obj) nameCards(obj) obj.randomize() end
    })
    deck.setCustomObject({face = faceImg, back = backImg, number = 66})
end

