        {"Purple Single", 18},
        {"Purple Double", 20},
        {"Yellow Single", 28},
        {"Yellow Double", 30},
        {"Blue Single", 38},
        {"Blue Double", 40},
        {"Orange Single", 48},
        {"Orange Double", 50},
        {"Green Single", 58},
        {"Green Double", 60},
        {"Candy Cane", 61},
        {"Ginderbread Man", 62},
        {"Peanut", 63},
        {"Lollypop", 64},
        {"Jello", 65},
        {"Ice Cream", 66}
    }
    object.setName("Candy Deck")
    local t = 1
    for i, card in ipairs(object.getObjects()) do
        table.insert(cardNames,{card.guid,deckContents[t][1]})
        if i == deckContents[t][2] then
            t = t + 1
        end
    end
end

function getCardName(c)
    for i, card in ipairs(cardNames) do
        if c.guid == card[1] then
            return card[2]
        end
    end
    return "Red Single[Error]"
end

