    if deck ~= nil then
        if tablelength(deck.getObjects()) == 2 then
            lastCard = deck.getObjects()[2].guid
        end
        card = deck.takeObject()
        cardName = getCardName(card)
        card.setName(cardName)
        toDiscard(card, false)
    else
        card = getObjectFromGUID(lastCard)
        cardName = getCardName(card)
        card.setName(cardName)
        toDiscard(card, true)
    end
    return cardName
end

function toDiscard(object, shuffle)
    local p = self.getPosition()
    local s = self.getScale()
    deckPos = {(s.x*-1.2)+p.x,p.y,(s.z*1.22)+p.z}
    discardPos = {(s.x*-0.85)+p.x,p.y,(s.z*1.22)+p.z}
    if discard ~= nil then
        discard = group({discard, object})[1]
        discard.setName("Candy Deck Discard")
        if shuffle then
            shuffleDiscard()
        end
    else
        discard = object
    end
    if discard ~= null then
        discard.setPosition(discardPos)
        discard.setRotation({0,180,0})
    end
    if deck ~= nil then
        deck.setPosition(deckPos)
        deck.setRotation({180,180,0})
    end
end

function shuffleDiscard()
    local p = self.getPosition()
    local s = self.getScale()
    local pos = {(s.x*-1.2)+p.x,1.3+p.y,(s.z*1.22)+p.z}
    if deck ~= nil then
        discard.setRotation({180,180,0})
        deck = group({deck, discard})[1]
    else
        deck = discard
    end
    discard = nil
    deck.setName("Candy Deck")
    deck.setRotation({180,180,0})
    if speedTable[speedIndex][2] > 1 then
        deck.setPositionSmooth(pos, false, speedTable[speedIndex][2] < 10)
    else
        deck.setPosition(pos)
    end
    deck.randomize()
end

function move(dest, player, direct)
    local goTo = player.space
    if direct then
        goTo = dest
    elseif player.space < dest then
        goTo = goTo + 1
    else
        goTo = goTo - 1
    end
    local snappoints = self.getSnapPoints()
    local pos = self.positionToWorld(snappoints[goTo].position)
    pos.y = pos.y + (0.17 * self.getScale().x)
    if speedTable[speedIndex][2] > 1 then
        player.pawn.setPositionSmooth(pos, false, speedTable[speedIndex][2] < 10)
        player.pawn.setRotationSmooth(snappoints[goTo].rotation, false, speedTable[speedIndex][2] < 10)
    else
        player.pawn.setPosition(pos)
        player.pawn.setRotation(snappoints[goTo].rotation)
    end
    player.space = goTo
    if goTo ~= dest then
        Wait.frames(function() move(dest,player) end, speedTable[speedIndex][2])
    else
        player.pawn.setRotationSmooth({0, snappoints[goTo].rotation.y + 180,0}, false, false)
    end
end

function nextSpace(dest, cardName)
    for j, item in ipairs(itemTable) do
        if item[1] == cardName then
            return item[2]
        end
    end
    t = string.match(cardName, "Single")
    for i, spc in ipairs(path) do
        if string.match(cardName, spc) and i > dest then
            if t then
                return i
            else
                t = true
            end
        end
    end
    return 134
end

function takeShortcuts(player)
    if player.space == 5 then
        broadcastTurn(player.name .. " takes a shortcut through the Rainbow Trail!", player.color)
        move(59, player, true)
        Wait.frames(function() createNextTurnButton() end, speedTable[speedIndex][3])
    elseif player.space == 35 then
        broadcastTurn(player.name .. " takes a shortcut through the Gumdrop Pass!", player.color)
        move(45, player, true)
        Wait.frames(function() createNextTurnButton() end, speedTable[speedIndex][3])
    else
        loseTurn(player)
    end
end

function loseTurn(player)
    if player.space == 46 or player.space == 86 or player.space == 117 then
        broadcastTurn(player.name .. " is stuck on a licorice space! Lose one turn...", player.color)
        player.loseTurn = true
        Wait.frames(function() createNextTurnButton() end, speedTable[speedIndex][3])
    else
        createNextTurnButton()
    end
end

function nextTurn()
    self.UI.hide("btnTakeTurn")
    takeTurn(playerList[currentTurn])
    if currentTurn < tablelength(playerList) then
        currentTurn = currentTurn + 1
    else
        currentTurn = 1
    end
end

function takeTurn(player)
    if player.loseTurn then
        broadcastTurn(player.name .. " is stuck on a licorice space! Skipping turn...", player.color)
        player.loseTurn = false
        Wait.frames(function() createNextTurnButton() end, speedTable[speedIndex][3])
    else
        local cardName = drawCard()
        local dest = nextSpace(player.space,cardName)
        local spaces = dest-player.space
        totalTurns = totalTurns + 1
        player.turns = player.turns + 1
        if spaces > 0 then
            broadcastTurn("Turn " .. totalTurns .. " : " .. player.name .. " draws a " .. cardName .. " card to move forward " .. spaces .. " spaces.", player.color)
        else
            spaces = spaces * -1
            broadcastTurn("Turn " .. totalTurns .. " : " .. player.name .. " draws a " .. cardName .. " card to move backward " .. spaces .. " spaces.", player.color)
        end
        move(dest, player, speedTable[speedIndex][2] == 0)
        local wait = (spaces * speedTable[speedIndex][2]) + speedTable[speedIndex][3]
        if dest == 134 then
            Wait.frames(function() playerWin(player) end, wait)
        else
            Wait.frames(function() takeShortcuts(player) end, wait)
        end
    end
end

function setTurn(color)
    Turns.enable = true
    Turns.turn_color = color
end

function playerWin(player)
    if setTurnOnWin then
        setTurn(player.color)
    end
    displayWinner(player)
    if broadcastWins then
        broadcastToAll(player.name .. " won the game in " .. player.turns .. " turns. Congratulations!", player.color)
    end
    if destroyOnWin then
        Wait.frames(function() self.destroy() end, 600)
    elseif autoGame then
        Wait.frames(function() playAgain() end, 120)
    else
        gameEnd = true
        self.UI.show("btnNewGame")
        self.UI.show("btnPlayAgain")
    end
end

function displayWinner(player)
    local playerColor = player.color
    local fontColor = "White"
    if playerColor == "White" or playerColor == "Yellow" or playerColor == "Teal" then
        fontColor = "Black"
    end
    self.UI.show("btnWinnerDisplay")
    self.UI.setAttribute("btnWinnerDisplay", "color", playerColor)
    self.UI.setAttribute("btnWinnerDisplay", "text", player.name .. " Wins. \nCongratulations!")
    self.UI.setAttribute("btnWinnerDisplay", "textColor", fontColor)
end

function playAgain()
    local p = self.getPosition()
    local s = self.getScale()
    local pos = 0
    local rot = {90,270,0}
    menuCleanup()
    if discard ~= nil then
        shuffleDiscard()
    end
    for i, player in ipairs(playerList) do
        player.space = 0
        player.turns = 0
        pos = {(s.x*(-0.97-(0.04*(i-1))))+p.x, (s.x*0.17)+p.y, (s.z*-0.92)+p.z}
        if speedTable[speedIndex][2] > 0 then
            player.pawn.setPositionSmooth(pos, true, speedTable[speedIndex][2] < 10)
            player.pawn.setRotationSmooth(rot, true, speedTable[speedIndex][2] < 10)
        else
            player.pawn.setPosition(pos)
            player.pawn.setRotation(rot)
        end
    end
    Wait.frames(function() startGame() end, 60)
end

function broadcastTurn(messege, color)
    if broadcastTurns then
        broadcastToAll(messege, color)
    end
end

function menuCleanup()
    self.UI.hide("btnStartGame")
    self.UI.hide("btnManualMode")
    self.UI.hide("btnFirstStartGame")
    self.UI.hide("btnNewGame")
    self.UI.hide("btnPlayAgain")
    self.UI.hide("btnWinnerDisplay")
end

function destroy(obj)
    if obj ~= nil then
        obj.destroy()
    end
end

function cleanUp()
    destroy(deck)
    destroy(discard)
    if playerList ~= nil then
        for i, player in ipairs(playerList) do
            destroy(player.pawn)
        end
    end
end

function onDestroy()
    cleanUp()
end
